def validate(body,params=()):
    """Resolve lexical labels and reject jumps that introduce live locals."""
    gotos=[]
    def scope(stmts,parent,initial):
        sc={'parent':parent,'labels':{}};active=list(initial)
        for index,n in enumerate(stmts):
            k=n.kind;a=n.a
            if k=='label':
                name=a[0]
                if name in sc['labels']:raise ParseError("duplicate label '%s'"%name,n.line)
                at_end=all(x.kind=='label' for x in stmts[index+1:])
                sc['labels'][name]=(n,list(initial if at_end else active))
            elif k=='goto':gotos.append((n,sc,set(active)))
            elif k=='local':active.extend((id(n),i,name) for i,name in enumerate(a[0]))
            elif k=='localfn':active.append((id(n),0,a[0]))
            elif k=='if':
                for c,b in a[0]:scope(b,sc,active)
                scope(a[1],sc,active)
            elif k=='do':scope(a[0],sc,active)
            elif k=='while':scope(a[1],sc,active)
            elif k=='repeat':scope(a[0],sc,active)
            elif k=='fornum':scope(a[4],sc,active+[(id(n),0,a[0])])
            elif k=='forin':scope(a[2],sc,active+[(id(n),i,name) for i,name in enumerate(a[0])])
        return sc
    scope(body,None,[('param',i,n) for i,n in enumerate(params)])
    for node,sc,active in gotos:
        name=node.a[0]
        while sc and name not in sc['labels']:sc=sc['parent']
        if not sc:raise ParseError("undefined label '%s'"%name,node.line)
        target,locals_=sc['labels'][name]
        missing=[x for x in locals_ if x not in active]
        if missing:raise ParseError("<goto %s> jumps into the scope of local '%s'"%(name,missing[0][2]),node.line)
    def functions(n):
        if isinstance(n,Node):
            if n.kind=='function':validate(n.a[2],n.a[0]);return
            for a in n.a:functions(a)
        elif isinstance(n,(list,tuple)):
            for a in n:functions(a)
    functions(body)
